def analyze_contract(query: str, contract: str):
    is_lookup = classify_query(query)  # own classifier
    params = {
        "model": "claude-sonnet-4-6",
        "max_tokens": 16000,
        "messages": [{"role": "user", "content": f"{query}\n\n{contract}"}],
    }
    if not is_lookup:
        # cross-clause reasoning → Extended Thinking
        params["thinking"] = {"type": "enabled", "budget_tokens": 10000}
    return client.messages.create(**params)
